def has_duplicates_slow(lst):
    for i, x in enumerate(lst):
        for y in lst[i+1:]:
            if x == y:
                return True
    return False

def has_duplicates_fast(lst):
    seen = set()
    for x in lst:
        if x in seen:
            return True
        seen.add(x)
    return False
